const sqlBody = {
  sql: "select * from qa_training.items_orden where id = $1",
  params: [25]
};

pm.sendRequest({
        url: pm.variables.get('baseUrl') + '/api/v1/sql/select',
        method: 'POST',
        header: { 'Content-Type': 'application/json', 'x-api-key': pm.variables.get('x-api-key') },
        body: { mode: 'raw', raw: JSON.stringify(sqlBody) }
    }, function (err, res) {
        if (err) { 
            console.error('Error en pre-request (usuario):', err); 
            return; 
        }

        // NUEVO: controlar 429 Too Many Requests
        if (res.code === 429) {
            pm.test("La consulta previa a la BD no debe responder 429 Too Many Requests", function () {
                pm.expect(res.code).to.not.eql(429);
            });

            console.error('La consulta previa a la BD respondió 429 Too Many Requests.');
            return;
        }

        // NUEVO: controlar respuesta que no sea JSON
        let body;

        try {
            body = res.json();
        } catch (e) {
            pm.test("La consulta previa a la BD devuelve un JSON válido", function () {
                pm.expect.fail("La respuesta no es un JSON válido. Status: " + res.code);
            });

            console.error('La respuesta de la consulta SQL no es JSON válido.');
            console.error('Respuesta recibida:', res.text());
            return;
        }

        if (!body.data || body.data.length === 0) {
            console.error('No se encontró producto en qa_training.ordenes');
            return;
        }

        const orden = body.data[0];
        pm.collectionVariables.set('ordenId', orden.id);
        pm.collectionVariables.set('producto', orden.producto);
        //console.log(body.data[0].producto);
});

const statusCode = pm.response.code; //collectionVariables

// NUEVO: controlar 429 antes de intentar convertir la respuesta a JSON
if (statusCode === 429) {

    pm.test("El código de respuesta es 429 Too Many Requests", () => {
        pm.response.to.have.status(429);
    });

    console.error("La API respondió 429 Too Many Requests.");
    
}
else {

    // NUEVO: controlar respuesta que no sea JSON
    let jsonData;

    try {
        jsonData = pm.response.json();
    } catch (e) {

        pm.test("La respuesta del endpoint es un JSON válido", function () {
            pm.expect.fail("La respuesta no es un JSON válido. Status: " + statusCode);
        });

        console.error("La respuesta del endpoint no es JSON válido.");
        console.error("Respuesta recibida:", pm.response.text());

        // No continuar con la lógica existente
        jsonData = null;
    }

    // Solo ejecutamos tu lógica actual cuando la respuesta es JSON
    if (jsonData !== null) {

        const errorMessage = jsonData.error;
        pm.collectionVariables.set('id', jsonData.data.id);

        if(statusCode === 201){
            pm.test("El código de respuesta es 201 Created",() => {
                pm.response.to.have.status(201);
            });

            pm.test("La respuesta contiene el objeto 'data' con la estructura correcta", function () {

                // Validamos que exista el objeto data
                pm.expect(jsonData).to.have.property('data');
            
            
                // Validamos que exista el array de items y su contenido
                pm.expect(jsonData.data.items).to.be.an('array').that.is.not.empty;
                pm.expect(jsonData.data.items[0].producto).to.eql("Soporte Premium");
            });
        }
        else if(statusCode === 400){

            //console.log(jsonData.error.code);
            pm.test("Code 400 - Body/query inválido o error de ejecución", () =>{
                pm.expect(errorMessage.code).to.eql("VALIDATION_ERROR");
            });

        }
        else if(statusCode === 401){
            pm.test("Code 401 - API key inválida, inactiva o ausente", () =>{
                pm.expect(errorMessage.code).to.eql("UNAUTHORIZED");
            });
        }

        const sqlBody = {
          sql: "SELECT id, activo FROM ordenes WHERE id = $1",
          params: [pm.collectionVariables.get('id')]
        };

        pm.sendRequest({
                url: pm.variables.get('baseUrl') + '/api/v1/sql/select',
                method: 'POST',
                header: { 'Content-Type': 'application/json', 'x-api-key': pm.variables.get('x-api-key') },
                body: { mode: 'raw', raw: JSON.stringify(sqlBody) }
                }, function (err, res) {

                if (err) { 
                    console.error('Error en pre-request (usuario):', err); 
                    return; 
                }

                // NUEVO: controlar 429 en la consulta de BD
                if (res.code === 429) {
                    pm.test("La consulta de BD no debe responder 429 Too Many Requests", function () {
                        pm.expect(res.code).to.not.eql(429);
                    });

                    console.error("La consulta de BD respondió 429 Too Many Requests.");
                    return;
                }

                // NUEVO: controlar respuesta no JSON en consulta de BD
                let body;

                try {
                    body = res.json();
                } catch (e) {
                    pm.test("La respuesta de la consulta de BD es un JSON válido", function () {
                        pm.expect.fail("La respuesta de la BD no es un JSON válido. Status: " + res.code);
                    });

                    console.error("La respuesta de la consulta de BD no es JSON válido.");
                    console.error("Respuesta recibida:", res.text());
                    return;
                }

                if (!body.data || body.data.length === 0) {
                    console.error('No se encontró producto en qa_training.ordenes');
                    return;
                }

                const orden = body.data[0];

                pm.test("La BD confirma que la orden ha sido creada", function () {
                    pm.expect(String(orden.activo)).to.eql("true");
                });

        });
    }
}

